import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, output, signal, untracked } from '@angular/core';
import { ClaimsApi, ClaimView } from '../../core/claims';
import { Session } from '../../core/session';

// The paste box: lines of name,amount,date,note each add a DRAFT claim for the named person, all or
// none; how many were added is shown.
@Component({
  selector: 'app-paste-claims',
  template: `
    <form (submit)="save($event)" aria-label="Paste claims">
      <label for="paste-claims">Paste claims, one per line: name,amount,date,note</label>
      <textarea
        id="paste-claims"
        data-testid="paste-claims"
        rows="4"
        [value]="text()"
        (input)="text.set(value($event)); error.set(null)"
      ></textarea>
      <button type="submit" data-testid="paste-submit">Add pasted claims</button>
      @if (added() !== null) {
        <p role="status">Added <strong data-testid="paste-added">{{ added() }}</strong> claims.</p>
      }
      @if (error(); as message) {
        <p role="alert" data-testid="paste-error">{{ message }}</p>
      }
    </form>
  `,
})
export class PasteClaims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);

  /** The claims pasted, in the order they were added. */
  readonly pasted = output<ClaimView[]>({ alias: 'added' });

  protected readonly text = signal('');
  protected readonly added = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // A sheet load starts the box afresh.
    effect(() => {
      this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.text.set('');
        this.added.set(null);
        this.error.set(null);
      });
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLTextAreaElement).value;
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    this.added.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const text = this.text();
    if (!text.trim()) {
      this.error.set('Paste at least one line of name,amount,date,note.');
      return;
    }
    this.busy = true;
    try {
      const claims = await this.api.paste(sheet, text);
      if (this.session.sheet() !== sheet) return;
      this.pasted.emit(claims);
      this.added.set(claims.length);
      this.text.set('');
    } catch (e) {
      const reason = e instanceof HttpErrorResponse && e.status === 400 && typeof e.error?.detail === 'string' ? e.error.detail : null;
      this.error.set(reason ?? 'The pasted claims could not be added; nothing was added.');
    } finally {
      this.busy = false;
    }
  }
}

  /** People imported: those updated replaced where they stand, those added each listed last in turn. */
  protected imported(imported: ImportView): void {
    this.people.update((list) => [
      ...list.map((p) => imported.updated.find((u) => u.id === p.id) ?? p),
      ...imported.added,
    ]);
  }

  /** Claims pasted or made by the plans, in the order added: each listed first in turn, so the last is the newest. */
  protected pasted(claims: ClaimView[]): void {
    for (const claim of claims) this.claimSaved(claim);
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected checked(event: Event): boolean {
    return (event.target as HTMLInputElement).checked;
  }

  protected gradeChosen(event: Event): Grade {
    return (event.target as HTMLSelectElement).value as Grade;
  }

  /**
   * Open a person's editor: the form takes their values as the store holds them now, so it edits from
   * their current version. The form stays empty until they are read.
   */
  protected async open(person: PersonView): Promise<void> {
    this.personError.set(null);
    this.editing.set(person.id);
    this.name.set('');
    this.error.set(null);
    const sheet = this.session.sheet();
    let current = person;
    if (sheet) {
      try {
        current = (await this.api.list(sheet)).find((p) => p.id === person.id) ?? person;
      } catch {

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Records outside a transaction are appended at once.
     */
    public void recordOnCommit(String entry) {
        recordAfterCommit(entry + actingFor());
    }

    /**
     * Append a record of the figures a change moved (ROLLUP and TOTALS) once the current transaction
     * commits; unlike the change's own records it never names a steward acted for.
     */
    public void recordFiguresOnCommit(String entry) {
        recordAfterCommit(entry);
    }

    /** " for=<steward>" when the signed-in user acts for a steward in this request, else empty. */
    private static String actingFor() {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
        return steward instanceof String name ? " for=" + name : "";
    }

    private void recordAfterCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** A field naming a person: name=&lt;value&gt; or person=&lt;value&gt;, the value running to the next field. */
    private static final java.util.regex.Pattern PERSON_FIELD =
            java.util.regex.Pattern.compile(" (?:name|person)=(.*?)(?= [^ =]+=|$)");

    /**
     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only
     * the lines carrying name=&lt;it&gt; or person=&lt;it&gt;, compared as names are compared.
     */
    public List<String> linesOf(String sheetId, String name) {
        return name == null || name.isBlank() ? linesAbout(sheetId, null) : linesAbout(sheetId, Set.of(Person.keyOf(name)));
    }

    /**
     * The sheet's lines exactly as the file holds them, newest first. With keys (not null), only the
     * lines carrying name=&lt;one&gt; or person=&lt;one&gt;, compared as names are compared.
     */
    public synchronized List<String> linesAbout(String sheetId, Set<String> keys) {
        List<String> lines;
        try {
            lines = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String sheetField = " sheet=" + sheetId + " ";
        List<String> shown = new ArrayList<>();
        for (String line : lines) {
            if (line.contains(sheetField) && (keys == null || isAbout(line, keys))) {
                shown.add(line);
            }
        }
        Collections.reverse(shown);
        return shown;
    }

    private static boolean isAbout(String line, Set<String> keys) {
        Matcher field = PERSON_FIELD.matcher(line);
        while (field.find()) {
            if (keys.contains(Person.keyOf(field.group(1)))) {
                return true;
            }
        }
        return false;
    }

