test("imported claims open scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-C", "20");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "tags": "b, a"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "20", "contact": "ADA@X", "tags": "a"}));
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00", "date": "2026-02-25", "note": "n"}));
  expect(await ui.addPatron(pg_uma, p_ada, "Cam")).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "4.00", "note": "n", "tags": " c "}));
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "delete")).toBe(true);
  await ui.refresh(pg_uma);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimAction(pg_wes, c_ada_0, "open")).toBe(true);
  expect(await ui.periodAction(pg_wes, "P2", "close")).toBe(true);
  expect(await ui.watch(pg_wes, p_ada, true)).toBe(true);
